 370→void UBridgeComponent::HandleTransitionState(const TSharedPtr<FJsonObject>& JsonObj)
 371→{
 372→    const TSharedPtr<FJsonObject>* TransObjPtr;
 373→    const TSharedPtr<FJsonObject>& TransData =
 374→        JsonObj->TryGetObjectField(TEXT("transition"), TransObjPtr) ? *TransObjPtr : JsonObj;
 375→
 376→    FString Direction = TransData->GetStringField(TEXT("direction"));
 377→    FString NextScene = TransData->GetStringField(TEXT("next_scene"));
 378→    float Progress = TransData->GetNumberField(TEXT("progress"));
 379→
 380→    BridgeLog(FString::Printf(TEXT("Transition: %s -> %s (%.0f%%)"),
 381→        *Direction, *NextScene, Progress * 100.0f));
 382→
 383→    OnTransitionReceived.Broadcast(Direction, NextScene);
 384→}
