 573→    FString Pattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *VariantSetName);
 574→    FRegexPattern RegexPattern(Pattern);
 575→    FRegexMatcher Matcher(RegexPattern, Content);
 576→
 577→    if (Matcher.FindNext())
