 585→FString UBridgeComponent::ParseUsdaAttribute(const FString& Content, const FString& PrimPath, const FString& AttrName)
 586→{
 587→    // Find the prim section and extract attribute value
 588→    // This is a simplified parser - handles basic string/int/float attributes
 589→
 590→    // First find the prim section
 591→    FString PrimPattern = FString::Printf(TEXT("def [^\"]*\"%s\"[^{]*\\{([^}]*)\\}"), *PrimPath);
 592→    FRegexPattern PrimRegex(PrimPattern);
 593→    FRegexMatcher PrimMatcher(PrimRegex, Content);
 594→
 595→    FString PrimContent;
 596→    if (PrimMatcher.FindNext())
 597→    {
 598→        PrimContent = PrimMatcher.GetCaptureGroup(1);
 599→    }
 600→    else
 601→    {
 602→        // Try finding nested prim
 603→        PrimContent = Content;
 604→    }
 605→
 606→    // Parse string attribute
 607→    FString StringPattern = FString::Printf(TEXT("string %s = \"([^\"]*)\""), *AttrName);
 608→    FRegexPattern StringRegex(StringPattern);
 609→    FRegexMatcher StringMatcher(StringRegex, PrimContent);
 610→    if (StringMatcher.FindNext())
 611→    {
 612→        return StringMatcher.GetCaptureGroup(1);
 613→    }
 614→
 615→    // Parse int attribute
 616→    FString IntPattern = FString::Printf(TEXT("int %s = (-?\\d+)"), *AttrName);
 617→    FRegexPattern IntRegex(IntPattern);
 618→    FRegexMatcher IntMatcher(IntRegex, PrimContent);
 619→    if (IntMatcher.FindNext())
 620→    {
 621→        return IntMatcher.GetCaptureGroup(1);
 622→    }
 623→
 624→    // Parse float/double attribute
 625→    FString FloatPattern = FString::Printf(TEXT("(?:float|double) %s = ([\\d.]+)"), *AttrName);
 626→    FRegexPattern FloatRegex(FloatPattern);
 627→    FRegexMatcher FloatMatcher(FloatRegex, PrimContent);
 628→    if (FloatMatcher.FindNext())
 629→    {
 630→        return FloatMatcher.GetCaptureGroup(1);
 631→    }
 632→
 633→    return TEXT("");
 634→}
