 740→void UBridgeComponent::SendAnswerUsda(const FString& QuestionId, int32 OptionIndex, float ResponseTimeMs)
 741→{
 742→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 743→    FString Content;
 744→
 745→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 746→    {
 747→        BridgeLog(TEXT("ERROR: Could not read bridge_state.usda for answer"));
 748→        // Fall back to JSON
 749→        SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 750→        return;
 751→    }
 752→
 753→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
 754→    FString SelectedLabel = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionLabels.Num())
 755→        ? CurrentQuestion.OptionLabels[OptionIndex] : TEXT("");
 756→    FString SelectedDirection = (OptionIndex >= 0 && OptionIndex < CurrentQuestion.OptionDirections.Num())
 757→        ? CurrentQuestion.OptionDirections[OptionIndex] : TEXT("");
 758→
 759→    // Update sync_status variant to "answer_received"
 760→    Content = UpdateUsdaVariant(Content, TEXT("sync_status"), TEXT("answer_received"));
 761→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("answer"));
 762→
 763→    // Update Answer prim attributes
 764→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("question_id"), QuestionId, true);
 765→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("option_index"), FString::FromInt(OptionIndex), false);
 766→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 767→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_label"), SelectedLabel, true);
 768→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("selected_direction"), SelectedDirection, true);
 769→    Content = UpdateUsdaAttribute(Content, TEXT("Answer"), TEXT("timestamp"), Timestamp, true);
 770→
 771→    // Update behavioral signals
 772→    UpdateBehavioralSignals(Content, ResponseTimeMs);
 773→
 774→    // Write back
 775→    int32 MaxRetries = 3;
 776→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 777→    {
 778→        if (FFileHelper::SaveStringToFile(Content, *FilePath))
 779→        {
 780→            BridgeLog(FString::Printf(TEXT("USD answer sent: %s = option %d (%.0fms)"),
 781→                *QuestionId, OptionIndex, ResponseTimeMs));
 782→            return;
 783→        }
 784→        FPlatformProcess::Sleep(0.1f);
 785→    }
 786→
 787→    BridgeLog(TEXT("ERROR: Failed to write USD answer, falling back to JSON"));
 788→    SendAnswer(QuestionId, OptionIndex, ResponseTimeMs);
 789→}
