 792→FString UBridgeComponent::UpdateUsdaVariant(const FString& Content, const FString& VariantSetName, const FString& NewValue)
 793→{
 794→    // Simple string replacement for variant - more reliable than regex
 795→    FString SearchPattern = FString::Printf(TEXT("string %s = \""), *VariantSetName);
 796→    int32 StartIdx = Content.Find(SearchPattern);
 797→    if (StartIdx == INDEX_NONE)
 798→    {
 799→        return Content;
 800→    }
 801→
 802→    StartIdx += SearchPattern.Len();
 803→    int32 EndIdx = Content.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 804→    if (EndIdx == INDEX_NONE)
 805→    {
 806→        return Content;
 807→    }
 808→
 809→    // Build new content
 810→    FString Result = Content.Left(StartIdx) + NewValue + Content.Mid(EndIdx);
 811→    return Result;
 812→}
