 815→FString UBridgeComponent::UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString)
 816→{
 817→    // Find attribute pattern and replace value
 818→    // For string: string attrName = "value"
 819→    // For numeric: int/float/double attrName = value
 820→
 821→    FString Result = Content;
 822→
 823→    if (bIsString)
 824→    {
 825→        // Find: string attrName = "..."
 826→        FString SearchPattern = FString::Printf(TEXT("string %s = \""), *AttrName);
 827→        int32 StartIdx = Result.Find(SearchPattern);
 828→        if (StartIdx != INDEX_NONE)
 829→        {
 830→            StartIdx += SearchPattern.Len();
 831→            int32 EndIdx = Result.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 832→            if (EndIdx != INDEX_NONE)
 833→            {
 834→                FString EscapedValue = NewValue.Replace(TEXT("\\"), TEXT("\\\\")).Replace(TEXT("\""), TEXT("\\\""));
 835→                Result = Result.Left(StartIdx) + EscapedValue + Result.Mid(EndIdx);
 836→            }
 837→        }
 838→    }
 839→    else
 840→    {
 841→        // Find numeric attributes: int/float/double attrName = value
 842→        TArray<FString> TypePrefixes = { TEXT("int"), TEXT("float"), TEXT("double"), TEXT("bool") };
 843→
 844→        for (const FString& TypePrefix : TypePrefixes)
 845→        {
 846→            FString SearchPattern = FString::Printf(TEXT("%s %s = "), *TypePrefix, *AttrName);
 847→            int32 StartIdx = Result.Find(SearchPattern);
 848→            if (StartIdx != INDEX_NONE)
 849→            {
 850→                StartIdx += SearchPattern.Len();
 851→                // Find end of value (newline or space or semicolon)
 852→                int32 EndIdx = StartIdx;
 853→                while (EndIdx < Result.Len())
 854→                {
 855→                    TCHAR C = Result[EndIdx];
 856→                    if (C == '\n' || C == '\r' || C == ';' || C == ' ' || C == '\t')
 857→                    {
 858→                        break;
 859→                    }
 860→                    EndIdx++;
 861→                }
 862→                Result = Result.Left(StartIdx) + NewValue + Result.Mid(EndIdx);
 863→                break;
 864→            }
 865→        }
 866→    }
 867→
 868→    return Result;
 869→}
