 872→void UBridgeComponent::UpdateBehavioralSignals(FString& Content, float ResponseTimeMs)
 873→{
 874→    // ═══════════════════════════════════════════════════════════════════════════════
 875→    // THINKINGMACHINES [He2025] BATCH-INVARIANCE COMPLIANT
 876→    // Same signals → Same routing → Same behavior
 877→    // FIXED thresholds ensure deterministic expert selection regardless of load
 878→    // ═══════════════════════════════════════════════════════════════════════════════
 879→
 880→    // PHASE 1: DETECT - Collect signals
 881→    ResponseTimes.Add(ResponseTimeMs);
 882→
 883→    // Calculate average response time (FIXED algorithm - sum/count)
 884→    float TotalTime = 0.0f;
 885→    for (float Time : ResponseTimes)
 886→    {
 887→        TotalTime += Time;
 888→    }
 889→    float AvgResponseTime = ResponseTimes.Num() > 0 ? TotalTime / ResponseTimes.Num() : 0.0f;
 890→
 891→    // FIXED THRESHOLDS (batch-invariant - same across all sessions)
 892→    const float HESITATION_THRESHOLD_MS = 10000.0f;   // 10 seconds
 893→    const float RAPID_CLICK_THRESHOLD_MS = 500.0f;    // 0.5 seconds
 894→    const float DEPLETED_AVG_THRESHOLD_MS = 15000.0f; // 15 seconds average
 895→    const int32 HESITATION_COUNT_THRESHOLD = 2;
 896→    const int32 RAPID_CLICK_COUNT_THRESHOLD = 3;
 897→
 898→    // Detect hesitation
 899→    bool bLongHesitation = ResponseTimeMs > HESITATION_THRESHOLD_MS;
 900→    if (bLongHesitation)
 901→    {
 902→        HesitationCount++;
 903→    }
 904→
 905→    // Detect rapid clicking
 906→    bool bRapidClick = ResponseTimeMs < RAPID_CLICK_THRESHOLD_MS && ResponseTimes.Num() > 1;
 907→    if (bRapidClick)
 908→    {
 909→        RapidClickCount++;
 910→    }
 911→
 912→    // PHASE 2: CASCADE - ADHD_MoE FIXED PRIORITY ROUTING
 913→    // Priority: Validator(1) > Scaffolder(2) > Restorer(3) > Refocuser(4) > Celebrator(5) > Socratic(6) > Direct(7)
 914→    // First match wins - NEVER skip or reorder
 915→
 916→    FString DetectedState = TEXT("focused");
 917→    FString RecommendedExpert = TEXT("Direct");
 918→    FString BurnoutLevel = TEXT("GREEN");
 919→    FString MomentumPhase = TEXT("rolling");
 920→
 921→    // Priority 1: Validator - frustrated, RED burnout, caps, negative signals
 922→    if (RapidClickCount > RAPID_CLICK_COUNT_THRESHOLD)
 923→    {
 924→        DetectedState = TEXT("frustrated");
 925→        RecommendedExpert = TEXT("Validator");
 926→        BurnoutLevel = TEXT("RED");
 927→        MomentumPhase = TEXT("crashed");
 928→    }
 929→    // Priority 2: Scaffolder - overwhelmed, stuck, too_many signals
 930→    else if (bLongHesitation || HesitationCount > HESITATION_COUNT_THRESHOLD)
 931→    {
 932→        DetectedState = TEXT("stuck");
 933→        RecommendedExpert = TEXT("Scaffolder");
 934→        BurnoutLevel = TEXT("ORANGE");
 935→        MomentumPhase = TEXT("declining");
 936→    }
 937→    // Priority 3: Restorer - depleted, ORANGE burnout, post-crash
 938→    else if (AvgResponseTime > DEPLETED_AVG_THRESHOLD_MS)
 939→    {
 940→        DetectedState = TEXT("depleted");
 941→        RecommendedExpert = TEXT("Restorer");
 942→        BurnoutLevel = TEXT("ORANGE");
 943→        MomentumPhase = TEXT("crashed");
 944→    }
 945→    // Priority 4: Refocuser - distracted, tangent signals
 946→    else if (ResponseTimes.Num() > 3 && ResponseTimeMs > AvgResponseTime * 2.0f)
 947→    {
 948→        DetectedState = TEXT("distracted");
 949→        RecommendedExpert = TEXT("Refocuser");
 950→        BurnoutLevel = TEXT("YELLOW");
 951→        MomentumPhase = TEXT("declining");
 952→    }
 953→    // Priority 5: Celebrator - task_complete, milestone reached
 954→    else if (CurrentQuestion.Index == CurrentQuestion.Total - 1)
 955→    {
 956→        DetectedState = TEXT("completing");
 957→        RecommendedExpert = TEXT("Celebrator");
 958→        BurnoutLevel = TEXT("GREEN");
 959→        MomentumPhase = TEXT("peak");
 960→    }
 961→    // Priority 6: Socratic - exploring, high energy, "what if" signals
 962→    else if (ResponseTimes.Num() >= 2 && ResponseTimeMs > 3000.0f && ResponseTimeMs < 8000.0f)
 963→    {
 964→        DetectedState = TEXT("exploring");
 965→        RecommendedExpert = TEXT("Socratic");
 966→        BurnoutLevel = TEXT("GREEN");
 967→        MomentumPhase = TEXT("building");
 968→    }
 969→    // Priority 7: Direct - focused, hyperfocused, flow state (DEFAULT)
 970→    else
 971→    {
 972→        DetectedState = TEXT("focused");
 973→        RecommendedExpert = TEXT("Direct");
 974→        BurnoutLevel = TEXT("GREEN");
 975→        MomentumPhase = (ResponseTimes.Num() > 5) ? TEXT("rolling") : TEXT("building");
 976→    }
 977→
 978→    // PHASE 3: LOCK - Parameters locked for this response (no further changes)
 979→
 980→    // PHASE 4: EXECUTE - Update signals in USD content
 981→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("last_response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 982→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("average_response_time_ms"), FString::SanitizeFloat(AvgResponseTime), false);
