1008→        SendAcknowledge();
1009→        return;
1010→    }
1011→
1012→    FString Timestamp = FDateTime::UtcNow().ToIso8601();
1013→
1014→    // Update message_type to "ack"
1015→    Content = UpdateUsdaVariant(Content, TEXT("message_type"), TEXT("ack"));
1016→
1017→    // Update Ack prim
1018→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("ready"), TEXT("true"), false);
1019→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("ue_version"), TEXT("5.7.2"), true);
1020→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("project"), TEXT("TranslatorsCard"), true);
1021→    Content = UpdateUsdaAttribute(Content, TEXT("Ack"), TEXT("timestamp"), Timestamp, true);
1022→
1023→    if (FFileHelper::SaveStringToFile(Content, *FilePath))
1024→    {
1025→        BridgeLog(TEXT("USD acknowledgment sent"));
1026→        bUsingUsdMode = true;
1027→    }
1028→    else
1029→    {
1030→        BridgeLog(TEXT("USD ack failed, sending JSON"));
